 world:WorldDefinition|null=null;context:PlanetContext|undefined;catalog:Catalog|null=null;private current:WorldProgress|null=null;private saved:Record<string,unknown>={};private last:string|null=null;private loadGeneration=0;private travelBusy=false;private legacyWorld:WorldDefinition|null=null;private legacyProgress:WorldProgress|null=null;private legacyPlayer:ContentPlayer;private journeys:{world:string;interior:string|null;x:number|null;angle:number;height:number;trail?:{interior:string|null;x:number|null}[];entry?:string|null}[]=[];private characterMemory:Record<string,string[]>={};
