   const position=this.host.position();if(p.interior===a.target){this.host.close();return}if(p.trail.length>=100){this.host.note('Demasiadas puertas encadenadas. Regresa primero.');return}p.trail.push({interior:p.interior,x:p.interior?position.x??p.interiorX:null});if(!p.interior){p.planet.angle=position.angle;p.planet.returnAnchor={id,angle:position.angle,height:position.height}}p.interior=a.target;p.interiorX=w.interiors[a.target].spawn.x;p.interiorFacing=arrivalFacing(p.interiorX,w.interiors[a.target].width);this.store();this.host.interior();return;
