  const title=route.system?c.systems.find(s=>s.id===route.system)!.name:route.theme?c.themes.find(t=>t.id===route.theme)!.name:route.galaxy?c.galaxies.find(g=>g.id===route.galaxy)!.name:'Universo de las Ideas';
