 resourceArt(id:string){const a=this.libraryAssets[id];return a?{...a,file:'library-'+id}:undefined}
 legacyPalette(){return [...this.legacyResources].map(id=>({id,kind:this.libraryAssets[id].kind,label:this.libraryAssets[id].label??id,art:this.resourceArt(id)!}))}
